        live = [svc.proc for svc in self.services if svc.proc is not None]

        def signal_group(proc, sig):
            try:
                os.killpg(os.getpgid(proc.pid), sig)
            except (ProcessLookupError, PermissionError):
                try:
                    proc.send_signal(sig)  # fallback: just the direct child
                except ProcessLookupError:
                    pass

        # phase 1: SIGTERM every child's whole process group
        for proc in live:
            signal_group(proc, signal.SIGTERM)
