result = await mcp.call_tool("tools", "ox-bridge-edit", {"path": "/workspace/test_supervisor.py", "edits": [{"old": "def test_shutdown_kills_children_and_log_is_coherent(run_supervisor):", "new": "def test_shutdown_kills_entire_process_tree(run_supervisor):
    """Regression: a service that spawns its own grandchild must be killed
    entirely (the supervisor signals the whole process group)."""
    marker = "supervise-test-nested-marker"
    h = run_supervisor([
        {
            "name": "nested",
            "cmd": f"/bin/sh -c '{sys.executable} {STABLE} {marker} & wait'",
        },
    ])
    assert h.wait_until(
        lambda: _pids_matching(marker), timeout=5
    ), "nested grandchild never appeared"
    rc = h.terminate(timeout=10)
    assert rc == 0
    deadline = time.monotonic() + 3
    while time.monotonic() < deadline and _pids_matching(marker):
        time.sleep(0.05)
    assert not _pids_matching(marker), (
        f"grandchild processes leaked: {_pids_matching(marker)}"
    )


def _pids_matching(needle):
    found = []
    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        try:
            with open(f"/proc/{entry}/cmdline", "rb") as f:
                cmdline = f.read().replace(b"\0", b" ").decode()
        except OSError:
            continue
        if needle in cmdline and "pytest" not in cmdline:
            found.append(int(entry))
    return found


